INSERT INTO school_teacher (
    teacher_id, teacher_name, college_name, college_code,
    sync_time, last_schedule_sync_time, sync_source
) VALUES (
    #{teacherId}, #{teacherName}, #{collegeName}, #{collegeCode},
    #{syncTime}, #{lastScheduleSyncTime}, #{syncSource}
)
ON DUPLICATE KEY UPDATE
    teacher_name = COALESCE(#{teacherName}, teacher_name),
    college_name = #{collegeName},
    college_code = COALESCE(#{collegeCode}, college_code),
    sync_time = #{syncTime},
    sync_source = #{syncSource}
